/**
 * #4337 (part of #434 Slice C): migration 20261109213000_signature_ceremony_stamp declares `stamp_signing_keys.id` as
 * `integer GENERATED BY DEFAULT AS IDENTITY`, and `prisma db push` builds it as `DEFAULT nextval('…_id_seq')` with an
 * owned sequence. Inserts that omit the id behave the same; explicit ids and identity resets do not. The dev and test path
 * (push + post-push.sql) must carry the migration's identity column.
 */
import { readFileSync } from 'node:fs';
import { Client } from 'pg';
import { describe, expect, it } from 'vitest';
import { db } from '../../integrations/db/client.js';
import { generateId } from '../../lib/id.js';
import { maintenanceUrl, withDbName } from '../dbWorkers.js';

describe('#4337 stamp_signing_keys.id is the migration identity on push + post-push', () => {
  it('is GENERATED BY DEFAULT AS IDENTITY, with no column default and no leftover push sequence', async () => {
    const [col] = await db.$queryRaw<Array<{ identity: string; has_default: boolean; push_seq: boolean }>>`
      SELECT a.attidentity::text AS identity, a.atthasdef AS has_default,
             to_regclass(quote_ident(current_schema()) || '.stamp_signing_keys_id_seq') IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = to_regclass(quote_ident(current_schema()) || '.stamp_signing_keys_id_seq') AND d.deptype = 'i')
               AS push_seq
      FROM pg_attribute a
      WHERE a.attrelid = to_regclass(quote_ident(current_schema()) || '.stamp_signing_keys') AND a.attname = 'id'`;
    expect(col).toEqual({ identity: 'd', has_default: false, push_seq: false });
  });
});

/** The #4337 conversion block, as written in prisma/stamp-key-identity-invariants.sql (its one DO block). */
const SIGNING = readFileSync(new URL('../../../prisma/stamp-key-identity-invariants.sql', import.meta.url), 'utf8');
const BLOCK = (() => {
  const from = SIGNING.indexOf('DO $$', SIGNING.indexOf('-- #4337 (#434 Slice C)'));
  return SIGNING.slice(from, SIGNING.indexOf('END $$;', from) + 'END $$;'.length);
})();

/**
 * A throwaway database holding `stamp_signing_keys` as `db push` builds it (a sequence default on `id`), after `setup`
 * (rows, or a different column state). Dropped WITH (FORCE) whatever failed; the admin client is closed even if the drop fails, and a
 * cleanup error never hides the test's own failure.
 */
async function withPushBuiltTable(setup: string, body: (pg: Client) => Promise<void>): Promise<void> {
  const name = `sk4337_${generateId().toLowerCase()}`;
  const admin = new Client({ connectionString: maintenanceUrl() });
  await admin.connect();
  let pg: Client | undefined;
  let failure: unknown;
  try {
    await admin.query(`CREATE DATABASE "${name}" TEMPLATE template0`);
    pg = new Client({ connectionString: withDbName(maintenanceUrl(), name) });
    await pg.connect();
    await pg.query(`CREATE TABLE stamp_signing_keys (id SERIAL PRIMARY KEY, key_material text NOT NULL,
      created_at timestamp(3) NOT NULL DEFAULT now(), retired_at timestamp(3))`);
    await pg.query(setup);
    await body(pg);
  } catch (e) {
    failure = e;
  } finally {
    await pg?.end().catch(() => undefined);
    try {
      await admin.query(`DROP DATABASE IF EXISTS "${name}" WITH (FORCE)`);
    } catch (e) {
      if (failure === undefined) failure = e;
    } finally {
      await admin.end().catch(() => undefined);
    }
  }
  if (failure !== undefined) throw failure;
}

const column = async (pg: Client) => (await pg.query<{ identity: string; has_default: boolean }>(
  `SELECT attidentity::text AS identity, atthasdef AS has_default FROM pg_attribute
    WHERE attrelid = 'stamp_signing_keys'::regclass AND attname = 'id'`)).rows[0];

describe('#4337 the conversion block in prisma/stamp-key-identity-invariants.sql', () => {
  it('converts push\'s sequence column, continues above the highest id, and accepts an explicit id', async () => {
    await withPushBuiltTable(`INSERT INTO stamp_signing_keys (key_material) VALUES ('a'), ('b'), ('c')`, async (pg) => {
      await pg.query(BLOCK);
      expect(await column(pg)).toEqual({ identity: 'd', has_default: false });
      expect((await pg.query(`SELECT to_regclass('stamp_signing_keys_id_seq') IS NOT NULL AS seq`)).rows[0].seq).toBe(true);
      // The identity continues above the 3 existing rows.
      expect((await pg.query(`INSERT INTO stamp_signing_keys (key_material) VALUES ('d') RETURNING id`)).rows[0].id).toBe(4);
      // BY DEFAULT: an explicit id is accepted (an ALWAYS identity would refuse it without OVERRIDING SYSTEM VALUE).
      expect((await pg.query(`INSERT INTO stamp_signing_keys (id, key_material) VALUES (100, 'e') RETURNING id`)).rows[0].id).toBe(100);
      // An identity reset works as on the migration path.
      await pg.query('ALTER TABLE stamp_signing_keys ALTER COLUMN id RESTART WITH 200');
      expect((await pg.query(`INSERT INTO stamp_signing_keys (key_material) VALUES ('f') RETURNING id`)).rows[0].id).toBe(200);
    });
  }, 60_000);

  it('on an empty table starts at 1, and a re-run leaves the identity untouched', async () => {
    await withPushBuiltTable('SELECT 1', async (pg) => {
      await pg.query(BLOCK);
      const seq = (await pg.query(`SELECT 'stamp_signing_keys_id_seq'::regclass::oid::text AS oid`)).rows[0].oid;
      await pg.query(BLOCK);
      expect((await pg.query(`SELECT 'stamp_signing_keys_id_seq'::regclass::oid::text AS oid`)).rows[0].oid).toBe(seq);
      expect((await pg.query(`INSERT INTO stamp_signing_keys (key_material) VALUES ('a') RETURNING id`)).rows[0].id).toBe(1);
    });
  }, 60_000);

  it.each([
    ['an ALWAYS identity', `ALTER TABLE stamp_signing_keys ALTER COLUMN id DROP DEFAULT; DROP SEQUENCE stamp_signing_keys_id_seq;
      ALTER TABLE stamp_signing_keys ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY`, /GENERATED ALWAYS/],
    ['another default', `ALTER TABLE stamp_signing_keys ALTER COLUMN id SET DEFAULT 7`, /has default 7, not push's sequence/],
  ])('refuses, changing nothing, for %s', async (_label, setup, refusal) => {
    await withPushBuiltTable(setup, async (pg) => {
      const before = await column(pg);
      await expect(pg.query(BLOCK)).rejects.toThrow(refusal);
      expect(await column(pg)).toEqual(before);
    });
  }, 60_000);
});
